#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  HMyEMF hEmf;  } Queue_FileEMF;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void ClearFileEMF(SQueue& q,void* s)  {  Queue_FileEMF* p = (Queue_FileEMF*)s;  EmfDelete( p->hEmf );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintFileEMF(DefinePaint)  {  QueueP(Queue_FileEMF);  //SetMnemoStyle( MNEMO_NONANTIAL );  //int nSave = ::SaveDC( hDC );  EmfPaint( p->hEmf, hDC, false, false );  //EmfPaint( p->hEmf, hDC, p->mRect );  //CMyPen pen( hDC, 0x00ff00 );  //pen.Rect( p->mRect );  //::RestoreDC( hDC, nSave );  //ClrMnemoStyle( MNEMO_NONANTIAL );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddFileEMF(DefineTegs)  {  AddQueueEx(Queue_FileEMF);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintFileEMF;  p->clear = &ClearFileEMF;  //  bool bDown = false;  STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },    { 'L', "down", &bDown },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  if ( !bDown ) ::SetRectEmpty( &p->mRect );  //  p->hEmf = EmfCreate();  CharMP szPath;  GetPathScn( szPath, teg[0].value, false );  lstrcat( szPath, ".emf" );  EmfOpen( p->hEmf, szPath );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~